EXAMPLES=[]
def ex(n,q,steps,answer,refs):
 EXAMPLES.append({'id':'we-5-source-'+str(n),'num':str(n),'title':'Example '+str(n),'problem':q,'given':'The source vector’s scalar component functions.','method':'Evaluate or test all components at the same parameter value.','steps':steps,'answer':answer,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':refs,'verification':'full question and source solution checked against JPG/PDF'}]})
ex(1,r'Find F⃗(π/2) and F⃗(π) for F⃗(t) = sin(t)î + cos(t)ĵ.',['Both sin t and cos t are defined for all real t, so the vector’s domain is ℝ.','At π/2, sin(π/2) = 1 and cos(π/2) = 0.','Thus F⃗(π/2) = 1î + 0ĵ = î.','At π, sinπ = 0 and cosπ = −1.','Thus F⃗(π) = 0î − 1ĵ = −ĵ.','Check lengths: sin²t + cos²t = 1, so both output vectors have magnitude 1.','The range is the unit circle in the î–ĵ plane; all components use the same t, so their ranges cannot be chosen independently.'],'F⃗(π/2) = î; F⃗(π) = −ĵ.',131)
ex(2,'Find domains of (a) F⃗(t) = 2tî − 3tĵ + t⁻¹k̂; (b) F⃗(t) = sint î + (1 − t)⁻¹ĵ + lnt k̂.',['A vector exists only where every component exists; intersect their real domains.','(a) 2t and −3t are defined for every real t.','The reciprocal 1/t excludes zero, so the common domain is ℝ ∖ {0}.','The source sentence writes +3t for the second component; its actual coefficient is −3t, without changing this domain.','(b) sin t has all-real domain, while 1/(1 − t) excludes t = 1.','The real logarithm ln t requires t > 0.','Intersect to obtain (0,1) ∪ (1,∞). Negative t and t = 0,1 are excluded.'],'(a) ℝ ∖ {0}; (b) (0,1) ∪ (1,∞).',132)
ex(3,'Find lim as t → 2 of F⃗(t) = (t² − 3)î + eᵗĵ + sin(πt)k̂.',['Each component is continuous at 2, so evaluate their limits directly.','For the î coefficient: lim(t² − 3) = 4 − 3 = 1.','For the ĵ coefficient: lim eᵗ = e².','For the k̂ coefficient: lim sin(πt) = sin2π = 0.','Combine as 1î + e²ĵ + 0k̂ = î + e²ĵ.','The same result is F⃗(2), consistent with continuity at 2.','Its magnitude is √(1 + e⁴); a vector limit retains direction/components, rather than being replaced by that scalar magnitude.'],'î + e²ĵ.',133)
ex(4,'For what t is F⃗(t) = (sint,(1 − t)⁻¹) continuous?',['The sine component is continuous for every real t.','The reciprocal component has denominator 1 − t.','It is undefined at t = 1 and continuous wherever that denominator is nonzero.','The common domain is ℝ ∖ {1}.','At every t₀ in that domain, each component limit equals its component value.','Thus the vector is continuous on (−∞,1) and (1,∞).','At 1 the reciprocal diverges, so there is no finite vector value or continuous extension.'],'Continuous for all real t ≠ 1.',133)
ex(5,'For what t is F⃗(t) = (sint,(1 − t)⁻¹,lnt) continuous?',['Sine is continuous for all real t.','The reciprocal component requires t ≠ 1 and is continuous there.','The real logarithm requires t > 0 and is continuous on that interval.','The intersection is (0,1) ∪ (1,∞).','At any point in this intersection all three component limits equal their values.','Therefore the vector is continuous exactly on those two intervals.','At 0 the logarithm diverges; at 1 the reciprocal diverges. Neither excluded point has a finite continuous extension.'],'Continuous for t > 0,t ≠ 1.',133)
